*/
scwin.ipt_nonSelect_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin ipt_nonSelect_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.noSelected(selfVar)
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods70014.ipt_nonSelect_onclick' }); }
};

/**
