/**
 * @method
 * @name scwin.dataLoading
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.dataLoading = function () {
    /* sdd-asis-lifecycle:begin dataLoading — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    blockLoading();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.hideLoading
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.hideLoading = function () {
    /* sdd-asis-lifecycle:begin hideLoading — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    ($.fn && $.fn.dialog ? $("#loading").dialog("close") : undefined);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.checkIt
 * @author Inswave
 * @date 2026. 09. 29
 * @param ver
 * @returns
 * @hidden N
*/
scwin.checkIt = function (ver) {
    /* sdd-asis-lifecycle:begin checkIt — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.obj = (document.form || { elements: [] });
    const subObj = document.iframe.searchForm.relDiscl;
    const nonSelectObj = $c.util.getComponent('ipt_nonSelect');
    let tmpVal = null;
    let arrLength = 0;
    const arrNo = ((ver.value).split("|"))[0];
    scwin.resetRtnVal(arrNo);
    if ((String(nonSelectObj.getValue() || "") !== "") === true) {
        scwin.chkArrNo = new Array(0);
        scwin.chkTitle = new Array(0);
        nonSelectObj.checked = false;
    }
    if (scwin.chkArrNo.length != 0) {
        arrLength = scwin.chkArrNo.length;
    }
    if (ver.checked === true) {
        tmpVal = (ver.value).split("|");
        scwin.chkArrNo[arrLength] = tmpVal[0];
        scwin.chkTitle[arrLength] = tmpVal[1];
    }
    scwin.rtnVal = scwin.chkArrNo.join(",") + "|" + scwin.chkArrNo.join("\n");
    (($c.util.getComponent("txt_docs")) && ($c.util.getComponent("txt_docs")).setValue ? ($c.util.getComponent("txt_docs")).setValue(scwin.chkTitle.join("<br/>")) : (($c.util.getComponent("txt_docs")) ? (($c.util.getComponent("txt_docs")).innerHTML = scwin.chkTitle.join("<br/>")) : void (scwin.chkTitle.join("<br/>"))));
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.resetRtnVal
 * @author Inswave
 * @date 2026. 09. 29
 * @param ver
 * @returns
 * @hidden N
*/
scwin.resetRtnVal = function (ver) {
    /* sdd-asis-lifecycle:begin resetRtnVal — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const tmpArr1 = new Array(0);
    const tmpArr2 = new Array(0);
    let cnt = 0;
    for (let i = 0; i < scwin.chkArrNo.length; i++) {
        if (scwin.chkArrNo[i] !== ver) {
            tmpArr1[cnt] = scwin.chkArrNo[i];
            tmpArr2[cnt] = scwin.chkTitle[i];
            cnt++;
        }
    }
    scwin.chkArrNo = new Array(0);
    scwin.chkTitle = new Array(0);
    scwin.chkArrNo = tmpArr1;
    scwin.chkTitle = tmpArr2;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.selected
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.selected = async function () {
    /* sdd-asis-lifecycle:begin fn_selected — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const chkObj = (document.formCheck || { elements: [] });
    let isChoice = false;
    const subObj = document.iframe.searchForm.relDiscl;
    if (scwin.chkArrNo.length != 0) {
        isChoice = true;
    }
    if (((String($c.util.getComponent('ipt_nonSelect').getValue() || "") !== "")) || isChoice) {
        (((((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).scwin || {})) !== scwin && typeof (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).scwin || {})).fn_setSelectedData === 'function' ? (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).scwin || {})).fn_setSelectedData('' + dma_pageContext.get("formKey") + '', '' + dma_pageContext.get("formKey") + '', decodeURIComponent('' + dma_pageContext.get("returnKey") + ''), scwin.chkArrNo.join(","), scwin.chkTitle.join("\n")) : void 0), $c.win.closePopup(['' + dma_pageContext.get("formKey") + '', '' + dma_pageContext.get("formKey") + '', decodeURIComponent('' + dma_pageContext.get("returnKey") + ''), scwin.chkArrNo.join(","), scwin.chkTitle.join("\n")]));
        $c.win.closePopup();
    } else {
        await $c.win.alert("해당사항이 없는 경우 '해당없음'을 체크 하십시오!");
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.noSelected
 * @author Inswave
 * @date 2026. 09. 29
 * @param ver
 * @returns
 * @hidden N
*/
scwin.noSelected = function (ver) {
    /* sdd-asis-lifecycle:begin fn_noSelected — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.obj = (document.form || { elements: [] });
    const subObj = document.iframe.searchForm.relDiscl;
    if (ver.checked === true) {
        if (subObj.value !== '') {
            for (let i = 0; i < subObj.relDiscl.length; i++) {
                subObj.relDiscl[i].checked = false;
            }
        }
        $c.util.getComponent('txt_docs').setLabel("");
        scwin.chkArrNo = new Array(0);
        scwin.chkTitle = new Array(0);
        scwin.chkArrNo[0] = '-';
        scwin.chkTitle[0] = '-';
    } else {
        scwin.chkArrNo = new Array(0);
        scwin.chkTitle = new Array(0);
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setCheckedCheckBox
 * @author Inswave
 * @date 2026. 09. 29
 * @param ver
 * @returns
 * @hidden N
*/
scwin.setCheckedCheckBox = function (ver) {
    /* sdd-asis-lifecycle:begin setCheckedCheckBox — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const subObj = document.iframe.searchForm.relDiscl;
    let tmpVal = null;
    if (ver != 0) {
        if (scwin.chkArrNo.length != 0) {
            for (let i = 0; i < scwin.chkArrNo.length; i++) {
                for (let k = 0; k < subObj.relDiscl.length; k++) {
                    tmpVal = (subObj.relDiscl[k].value).split("|");
                    if (scwin.chkArrNo[i] === tmpVal[0]) {
                        subObj.relDiscl[k].checked = true;
                    }
                }
            }
        }
    }
    /* sdd-asis-lifecycle:end */
};
